export const fleetMaster = {
  api_mst_stype: STYPES.map(([id, ja]) => ({ api_id: id, api_name: ja })),
  api_mst_ship: SHIPS.map(([id, ja, , stype, ctype, after, sortId]) => ({
    api_id: id,
    api_name: ja,
    api_stype: stype,
    api_ctype: ctype,
    api_sortno: 1,
    api_sort_id: sortId ?? 1000 + id,
    api_aftershipid: `${after}`,
  })),
  api_mst_shipupgrade: [],
}

export const fleetLocalization = {
  entities: {
    shipType: Object.fromEntries(STYPES.map(([id, ja, zh]) => [`${id}`, { ja, zh }])),
    ship: Object.fromEntries(SHIPS.map(([id, ja, zh]) => [`${id}`, { ja, zh }])),
  },
}
